// Requirement: Реестр раннеров; Аутентификация агента по токену.
// Change multi-user (spec runner-enrollment, design M1/M4): runner ids generated by the hub, names and hostnames unique
// per owner, enrollment codes exchanged once for a token, the next token kept until the agent connects with it.
import { randomBytes } from 'node:crypto';
import { ENROLL_CODE_TTL_MS, isCompatibleProtocol, type EnrollStage, type RunnerView } from '@agent-hub/shared';
import { sql } from 'kysely';
import type { Db, RunnersTable } from '../db/db.js';
import { hashSecret, newSecret, safeEqual } from '../auth/secrets.js';
import type { Selectable } from 'kysely';

export type RunnerRow = Selectable<RunnersTable>;

/** Postgres NOTIFY channel: a runner token was reissued; payload is the runner id. */
export const TOKEN_CHANNEL = 'agenthub_runner_token';

/** "0.10.1" < "0.11.0"; anything unparsable is not compared (not outdated). */
export function versionLess(a: string, b: string): boolean {
  const pa = /^(\d+)\.(\d+)\.(\d+)/.exec(a);
  const pb = /^(\d+)\.(\d+)\.(\d+)/.exec(b);
  if (!pa || !pb) return false;
  for (let i = 1; i <= 3; i++) {
    const d = Number(pa[i]) - Number(pb[i]);
    if (d !== 0) return d < 0;
  }
  return false;
}

/** `latestAgent` — the version of the build the hub serves (null — none): «устарела». */
export function toRunnerView(r: RunnerRow, latestAgent: string | null = null): RunnerView {
  return {
    id: r.id,
    name: r.name,
    kind: r.kind,
    os: r.os,
    online: r.online,
    lastSeenAt: r.last_seen_at ? r.last_seen_at.toISOString() : null,
    agentVersion: r.agent_version,
    claudeVersion: r.claude_version,
    protocolVersion: r.protocol_version,
    incompatible: r.protocol_version !== null && !isCompatibleProtocol(r.protocol_version),
    vaultRoot: r.vault_root,
    homeDir: r.home_dir,
    state: r.state,
    claudeLogin: r.claude_login,
    protectedDirsOk: r.protected_dirs_ok,
    arch: r.arch,
    runsAsRoot: r.runs_as_root,
    outdated: Boolean(latestAgent && r.agent_version && versionLess(r.agent_version, latestAgent)),
    update: r.update_state ? { version: r.update_state.version, status: r.update_state.status, error: r.update_state.error, at: r.update_state.at } : null,
    providers: r.providers ?? [],
  };
}

/**
 * Machine runners of a user in registration order (k8s runners are not shown in MVP). By default only `active` ones:
 * the sidebar footer and the new-session form (a pending machine is not connected yet, a disabled one is gone).
 */
export async function listRunnerViews(db: Db, userId: string, opts: { all?: boolean; latestAgent?: string | null } = {}): Promise<RunnerView[]> {
  let q = db.selectFrom('runners').selectAll().where('user_id', '=', userId).where('kind', '=', 'machine');
  if (!opts.all) q = q.where('state', '=', 'active');
  const rows = await q.orderBy('created_at').orderBy('id').execute();
  return rows.map(r => toRunnerView(r, opts.latestAgent ?? null));
}

export async function getRunner(db: Db, id: string): Promise<RunnerRow | undefined> {
  return db.selectFrom('runners').selectAll().where('id', '=', id).executeTakeFirst();
}

/** Requirement: Разделение пространств — the runner of this user, or undefined (another user's runner too). */
export async function getOwnedRunner(db: Db, userId: string, id: string): Promise<RunnerRow | undefined> {
  return db.selectFrom('runners').selectAll().where('id', '=', id).where('user_id', '=', userId).executeTakeFirst();
}

/**
 * Finds the runner whose token hash matches — the current one or the next one of an enrollment (`next: true`). Every
 * candidate is compared with timingSafeEqual, so the time does not depend on which runner (if any) matches. Runners in
 * state `disabled` and runners of disabled users are not candidates (multi-user M4).
 */
export async function findRunnerAuth(db: Db, token: string): Promise<{ runner: RunnerRow; next: boolean } | null> {
  const presented = hashSecret(token);
  const rows = await db
    .selectFrom('runners')
    .innerJoin('users', 'users.id', 'runners.user_id')
    .select(['runners.id', 'runners.token_hash', 'runners.token_hash_next'])
    .where(eb => eb.or([eb('runners.token_hash', 'is not', null), eb('runners.token_hash_next', 'is not', null)]))
    .where('runners.state', '<>', 'disabled')
    .where('users.status', '=', 'active')
    .execute();
  let match: { id: string; next: boolean } | null = null;
  for (const r of rows) {
    if (r.token_hash && safeEqual(r.token_hash, presented)) match = { id: r.id, next: false };
    if (r.token_hash_next && safeEqual(r.token_hash_next, presented)) match = { id: r.id, next: true };
  }
  if (!match) return null;
  const runner = await getRunner(db, match.id);
  return runner ? { runner, next: match.next } : null;
}

export async function findRunnerByToken(db: Db, token: string): Promise<RunnerRow | null> {
  return (await findRunnerAuth(db, token))?.runner ?? null;
}

/** The first connection with the next token: it becomes the token, the previous one stops working. */
export async function promoteNextToken(db: Db, runnerId: string): Promise<void> {
  await db
    .updateTable('runners')
    .set({ token_hash: sql`token_hash_next`, token_hash_next: null })
    .where('id', '=', runnerId)
    .where('token_hash_next', 'is not', null)
    .execute();
}

export async function addRunner(db: Db, r: { id: string; userId: string; name: string; os?: string | null; isUtility?: boolean }): Promise<RunnerRow> {
  return db
    .insertInto('runners')
    .values({ id: r.id, user_id: r.userId, name: r.name, os: r.os ?? null, is_utility: r.isUtility ?? false })
    .returningAll()
    .executeTakeFirstOrThrow();
}

/** Issues a new token (revoking the previous one) and notifies running hubs. Returns the token, shown once. Tests only since multi-user. */
export async function issueRunnerToken(db: Db, id: string): Promise<string> {
  const token = newSecret();
  const r = await db
    .updateTable('runners')
    .set({ token_hash: hashSecret(token), token_hash_next: null })
    .where('id', '=', id)
    .executeTakeFirst();
  if (Number(r.numUpdatedRows) !== 1) throw new Error(`runner not found: ${id}`);
  await sql`SELECT pg_notify(${TOKEN_CHANNEL}, ${id})`.execute(db);
  return token;
}

// ---------- ids, names, codes (design M1, M4) ----------

const B32 = 'abcdefghijklmnopqrstuvwxyz234567';

function base32(bytes: Buffer, chars: number): string {
  let bits = 0;
  let value = 0;
  let out = '';
  for (const b of bytes) {
    value = (value << 8) | b;
    bits += 8;
    while (bits >= 5 && out.length < chars) {
      out += B32[(value >>> (bits - 5)) & 31];
      bits -= 5;
    }
  }
  return out;
}

/** `r-` + 10 base32 characters (50 bits): passes the runners.id CHECK; ids of the CLI era (hp, vm, x1) stay. */
export function newRunnerId(): string {
  return `r-${base32(randomBytes(7), 10)}`;
}

/** 26 base32 characters, 130 bits (spec: not shorter than 128). */
export function newEnrollCode(): string {
  return base32(randomBytes(17), 26);
}

export class RunnerNameTaken extends Error {
  constructor() {
    super('name_taken');
  }
}

function isUniqueViolation(err: unknown, constraint: string): boolean {
  const e = err as { code?: string; constraint?: string };
  return e.code === '23505' && e.constraint === constraint;
}

/**
 * Requirement: Код подключения — a `pending` runner of the user. Without a name: `defaultName` (the request language), then «<name> 2», …
 * A taken explicit name → RunnerNameTaken.
 */
export async function createPendingRunner(db: Db, userId: string, opts: { name?: string | undefined; os: string; defaultName: string }): Promise<RunnerRow> {
  const taken = new Set((await db.selectFrom('runners').select('name').where('user_id', '=', userId).execute()).map(r => r.name));
  let name = opts.name?.trim();
  if (name && taken.has(name)) throw new RunnerNameTaken();
  if (!name) {
    name = opts.defaultName;
    for (let i = 2; taken.has(name); i++) name = `${opts.defaultName} ${i}`;
  }
  for (let attempt = 0; ; attempt++) {
    try {
      return await db.insertInto('runners').values({ id: newRunnerId(), user_id: userId, name, os: opts.os, state: 'pending' }).returningAll().executeTakeFirstOrThrow();
    } catch (err) {
      if (isUniqueViolation(err, 'runners_user_name_key')) throw new RunnerNameTaken();
      if (attempt < 3 && isUniqueViolation(err, 'runners_pkey')) continue;
      throw err;
    }
  }
}

/** A machine added in «Подключить машину» whose code was never used is dropped after this long (hourly cleanup). */
export const PENDING_RUNNER_TTL_MS = 24 * 60 * 60_000;

/**
 * Requirement: Экран «Машины» — `pending` runners older than 24 h with no used code (the install never ran) are deleted;
 * a pending runner whose code was exchanged is kept (the agent may still connect). A runner some row still points at
 * without ON DELETE CASCADE / SET NULL — sessions (002), transcript_files (006), handoff_drafts (014) — is kept too,
 * with its data: it is excluded up front, and a reference of a table added later (foreign-key violation) skips that
 * runner instead of failing the whole cleanup. enroll_codes and pending_agent_meta go with it (CASCADE),
 * security_events keep their rows (SET NULL). Returns the number deleted.
 */
export async function deleteStalePendingRunners(db: Db, now = new Date()): Promise<number> {
  const stale = await db
    .selectFrom('runners')
    .select('id')
    .where('state', '=', 'pending')
    .where('created_at', '<', new Date(now.getTime() - PENDING_RUNNER_TTL_MS))
    .where(({ not, exists, selectFrom }) => not(exists(selectFrom('enroll_codes as c').select('c.runner_id').whereRef('c.runner_id', '=', 'runners.id').where('c.used_at', 'is not', null))))
    .where(({ not, exists, selectFrom }) => not(exists(selectFrom('sessions as s').select('s.id').whereRef('s.runner_id', '=', 'runners.id'))))
    .where(({ not, exists, selectFrom }) => not(exists(selectFrom('transcript_files as f').select('f.id').whereRef('f.runner_id', '=', 'runners.id'))))
    .where(({ not, exists, selectFrom }) => not(exists(selectFrom('handoff_drafts as h').select('h.id').whereRef('h.runner_id', '=', 'runners.id'))))
    .execute();
  let deleted = 0;
  for (const { id } of stale) {
    try {
      // state re-checked: the agent may have connected since the select
      const r = await db.deleteFrom('runners').where('id', '=', id).where('state', '=', 'pending').executeTakeFirst();
      deleted += Number(r.numDeletedRows);
    } catch (err) {
      if ((err as { code?: string }).code !== '23503') throw err;
    }
  }
  return deleted;
}

export async function renameRunner(db: Db, userId: string, id: string, name: string): Promise<RunnerRow | undefined> {
  try {
    return await db.updateTable('runners').set({ name: name.trim() }).where('id', '=', id).where('user_id', '=', userId).returningAll().executeTakeFirst();
  } catch (err) {
    if (isUniqueViolation(err, 'runners_user_name_key')) throw new RunnerNameTaken();
    throw err;
  }
}

/** «Новый код» / «Переподключить»: the previous unused code of the runner is revoked. */
export async function issueEnrollCode(db: Db, runner: Pick<RunnerRow, 'id' | 'user_id'>, now = new Date()): Promise<{ code: string; expiresAt: Date }> {
  const code = newEnrollCode();
  const expiresAt = new Date(now.getTime() + ENROLL_CODE_TTL_MS);
  await db.transaction().execute(async tx => {
    await tx.updateTable('enroll_codes').set({ revoked_at: now }).where('runner_id', '=', runner.id).where('used_at', 'is', null).where('revoked_at', 'is', null).execute();
    await tx
      .insertInto('enroll_codes')
      .values({ code_hash: hashSecret(code.toLowerCase()), runner_id: runner.id, user_id: runner.user_id, created_at: now, expires_at: expiresAt })
      .execute();
  });
  return { code, expiresAt };
}

export type RedeemResult = { ok: true; runner: RunnerRow; token: string } | { ok: false; error: 'code_used' | 'code_expired' | 'code_invalid' };

/**
 * Requirement: Код подключения — the exchange, once: `UPDATE … WHERE used_at IS NULL AND expires_at > now() RETURNING`
 * in a transaction, so two exchanges of one code cannot both win. A pending runner gets its first token; a connected
 * one keeps its token until the agent connects with the new one (`token_hash_next`, scenario «Повторный запуск»).
 */
export async function redeemEnrollCode(db: Db, code: string, machine: { os: string; arch: string }, now = new Date()): Promise<RedeemResult> {
  const hash = hashSecret(code.toLowerCase());
  return db.transaction().execute(async (tx): Promise<RedeemResult> => {
    const used = await tx
      .updateTable('enroll_codes')
      .set({ used_at: now, stage: 'code_used' })
      .where('code_hash', '=', hash)
      .where('used_at', 'is', null)
      .where('revoked_at', 'is', null)
      .where('expires_at', '>', now)
      .returning(['runner_id', 'user_id'])
      .executeTakeFirst();
    if (!used) {
      const row = await tx.selectFrom('enroll_codes').select(['used_at', 'revoked_at', 'expires_at']).where('code_hash', '=', hash).executeTakeFirst();
      if (!row || row.revoked_at) return { ok: false, error: 'code_invalid' };
      if (row.used_at) return { ok: false, error: 'code_used' };
      return { ok: false, error: 'code_expired' };
    }
    const owner = await tx.selectFrom('users').select('status').where('id', '=', used.user_id).executeTakeFirst();
    const current = await tx.selectFrom('runners').select(['state', 'token_hash']).where('id', '=', used.runner_id).executeTakeFirst();
    // A machine disabled (or a user disabled) after the code was issued: the code is spent, nothing is issued.
    if (!owner || owner.status !== 'active' || !current || current.state === 'disabled') return { ok: false, error: 'code_invalid' };
    const token = newSecret();
    const set = current.token_hash ? { token_hash_next: hashSecret(token) } : { token_hash: hashSecret(token), token_hash_next: null };
    const runner = await tx
      .updateTable('runners')
      .set({ ...set, os: machine.os, arch: machine.arch })
      .where('id', '=', used.runner_id)
      .returningAll()
      .executeTakeFirstOrThrow();
    return { ok: true, runner, token };
  });
}

/** The latest code of the runner: its stage for the window opened later (GET /api/runners/:id). */
export async function latestEnroll(db: Db, runnerId: string): Promise<{ stage: EnrollStage; codeExpiresAt: string | null } | null> {
  const row = await db
    .selectFrom('enroll_codes')
    .select(['stage', 'expires_at', 'used_at'])
    .where('runner_id', '=', runnerId)
    .where('revoked_at', 'is', null)
    .orderBy('created_at', 'desc')
    .limit(1)
    .executeTakeFirst();
  return row ? { stage: row.stage, codeExpiresAt: row.used_at ? null : row.expires_at.toISOString() } : null;
}

/** Moves the latest used code of the runner forward (code_used → connected → claude_checked → ready); returns the stages passed. */
export async function advanceEnroll(db: Db, runnerId: string, to: EnrollStage[]): Promise<EnrollStage[]> {
  const row = await db
    .selectFrom('enroll_codes')
    .select(['code_hash', 'stage'])
    .where('runner_id', '=', runnerId)
    .where('used_at', 'is not', null)
    .orderBy('used_at', 'desc')
    .limit(1)
    .executeTakeFirst();
  if (!row || row.stage === 'ready') return [];
  const order: EnrollStage[] = ['waiting', 'code_used', 'connected', 'claude_checked', 'ready'];
  const passed = to.filter(s => order.indexOf(s) > order.indexOf(row.stage));
  if (!passed.length) return [];
  await db
    .updateTable('enroll_codes')
    .set({ stage: passed[passed.length - 1]! })
    .where('code_hash', '=', row.code_hash)
    .execute();
  return passed;
}

/** Requirement: Экран «Машины» — «Отключить»: tokens revoked at once, the agent is closed by the caller (4401). */
export async function disableRunner(db: Db, userId: string, id: string, now = new Date()): Promise<RunnerRow | undefined> {
  return db.transaction().execute(async tx => {
    const r = await tx
      .updateTable('runners')
      .set({ state: 'disabled', token_hash: null, token_hash_next: null, online: false })
      .where('id', '=', id)
      .where('user_id', '=', userId)
      .returningAll()
      .executeTakeFirst();
    if (r) await tx.updateTable('enroll_codes').set({ revoked_at: now }).where('runner_id', '=', id).where('used_at', 'is', null).where('revoked_at', 'is', null).execute();
    return r;
  });
}
